//! Validation of the factory preset library `presets/factory.json` (SPEC §9).
//!
//! The library is generated by `tools/presets/generate.py` from `tools/presets/library.py`;
//! these tests check the shipped file itself against the format (`pixl_core::preset`) and
//! the library invariants, so a hand edit or a stale generator cannot slip through:
//!
//! - it parses as a [`PresetLibrary`] and every preset resolves with zero warnings;
//! - exactly 128 presets numbered 1..=128 in the SPEC's category ranges, unique names;
//! - metadata: icons, tags `[CHIP, CATEGORY, WAVE-TYPE]`, RU + EN descriptions;
//! - sound: at least one enabled channel, the icon's channel is enabled, every preset
//!   stores every parameter and a full wave RAM;
//! - macros: every macro has at least one routing, no routing is lost while loading
//!   (unknown or non-modulatable targets, duplicates, depths below `MIN_DEPTH`, overflow),
//!   and every routing moves its target;
//! - 014 "Hyrule Fanfare" is exactly the init state, and the design's twelve keep their
//!   names, categories, chips, icons and Russian descriptions;
//! - the generator's Python mirror of the parameter table and macro constants
//!   (`tools/presets/param_table.txt`, written by generate.py from pixl_params.py) is
//!   identical to the Rust table, so the macro depths it computes match the engine's maths.

use pixl_core::macros::{apply_macros, MacroAssignments, MACRO_COUNT, MACRO_NAMES, MACRO_SLOTS, MIN_DEPTH};
use pixl_core::params::{ChannelField, ParamId, ParamKind, ParamValues, PARAMS, PARAM_COUNT};
use pixl_core::preset::{Category, Preset, PresetIcon, PresetLibrary, LIBRARY_FORMAT, PRESET_FORMAT};
use pixl_core::{wave, Channel, ChipMode};
use std::collections::BTreeSet;

const FACTORY_JSON: &str = include_str!("../../../presets/factory.json");
/// The generator's mirror of the parameter table (see `python_mirror_matches_the_parameter_table`).
const MIRROR_LISTING: &str = include_str!("../../../tools/presets/param_table.txt");

