/// Category, first and last display number, count (SPEC §9).
const CATEGORY_RANGES: [(Category, u32, u32); 6] = [
    (Category::Lead, 1, 32),
    (Category::Bass, 33, 56),
    (Category::Arp, 57, 74),
    (Category::Pad, 75, 86),
    (Category::Drum, 87, 108),
    (Category::Sfx, 109, 128),
];

const INIT_NUMBER: u32 = 14;

fn library() -> PresetLibrary {
    PresetLibrary::from_json(FACTORY_JSON).expect("presets/factory.json must parse as a pixl-library")
}

fn label(p: &Preset) -> String {
    format!("{:03} {}", p.number, p.name)
}

fn macro_values(values: &ParamValues) -> [f32; MACRO_COUNT] {
    std::array::from_fn(|m| values.get(ParamId::macro_value(m)) / 100.0)
}

#[test]
fn parses_with_zero_warnings() {
    let lib = library();
    assert_eq!(lib.format, LIBRARY_FORMAT);
    assert_eq!(lib.version, 1);
    for p in &lib.presets {
        assert_eq!(p.format, PRESET_FORMAT, "{}", label(p));
        assert_eq!(p.version, 1, "{}", label(p));
        assert_eq!(p.author, "PIXL Factory", "{}", label(p));
        let (_, warnings) = p.to_state();
        assert!(warnings.is_empty(), "{}: {warnings:?}", label(p));
        // Each preset is also a valid stand-alone preset document.
        let back = Preset::from_json(&p.to_json()).unwrap_or_else(|e| panic!("{}: {e}", label(p)));
        assert_eq!(&back, p, "{}: JSON round trip", label(p));
    }
}

#[test]
fn numbers_categories_and_names() {
    let lib = library();
    assert_eq!(lib.presets.len(), 128);
    let numbers: BTreeSet<u32> = lib.presets.iter().map(|p| p.number).collect();
    assert_eq!(numbers, (1..=128).collect::<BTreeSet<u32>>(), "numbers must be exactly 1..=128");
    for (category, first, last) in CATEGORY_RANGES {
        let in_cat: Vec<&Preset> = lib.presets.iter().filter(|p| p.category == category).collect();
        assert_eq!(in_cat.len() as u32, last - first + 1, "{category:?} count");
        for p in in_cat {
            assert!((first..=last).contains(&p.number), "{} must be numbered {first:03}-{last:03}", label(p));
        }
    }
    let mut names = BTreeSet::new();
    for p in &lib.presets {
        let name = p.name.trim();
        assert!(!name.is_empty() && name == p.name, "{}: name must be trimmed and non-empty", label(p));
        assert!(name.chars().count() <= 18, "{}: name too long for the header pill", label(p));
        assert!(names.insert(name.to_lowercase()), "{}: duplicate name", label(p));
    }
}

#[test]
fn metadata_tags_icons_and_descriptions() {
    for p in &library().presets {
        let (state, _) = p.to_state();
        let chip = state.values.chip();
        assert_eq!(p.chip(), chip, "{}", label(p));
        assert_eq!(
            p.tags,
            vec![chip.label().to_string(), p.category.tag().to_string(), p.icon.tag().to_string()],
            "{}: tags must be [CHIP, CATEGORY, WAVE-TYPE]",
            label(p)
        );
        for (lang, text) in [("ru", &p.description.ru), ("en", &p.description.en)] {
            let t = text.trim();
            assert!(!t.is_empty(), "{}: empty {lang} description", label(p));
            assert!(t.ends_with(['.', '!', '?', '…']), "{}: {lang} description must be complete sentences", label(p));
            let sentences = t
                .match_indices(['.', '!', '?', '…'])
                .filter(|(i, s)| t[i + s.len()..].starts_with(' ') || i + s.len() == t.len())
                .count();
            assert!((1..=2).contains(&sentences), "{}: {lang} description must have one or two sentences", label(p));
        }
        let cyrillic = |s: &str| s.chars().any(|c| matches!(c, 'А'..='я' | 'Ё' | 'ё'));
        assert!(cyrillic(&p.description.ru), "{}: Russian description expected", label(p));
        assert!(!cyrillic(&p.description.en), "{}: English description contains Cyrillic", label(p));
        // The icon shows a channel that actually plays.
        let on = |c: Channel| state.values.bool(ParamId::channel(c, ChannelField::On));
        let icon_channel_on = match p.icon {
            PresetIcon::P12 | PresetIcon::P50 => on(Channel::P1) || on(Channel::P2),
            PresetIcon::Tri | PresetIcon::Wav => on(Channel::Wave),
            PresetIcon::Noi => on(Channel::Noise),
        };
        assert!(icon_channel_on, "{}: icon {:?} but that channel is off", label(p), p.icon);
        assert!(!(chip == ChipMode::Nes && p.icon == PresetIcon::Wav), "{}: NES has no wave RAM", label(p));
    }
}

#[test]
fn every_preset_is_complete_and_playable() {
    for p in &library().presets {
        if p.number == INIT_NUMBER {
            continue;
        }
        assert_eq!(p.params.len(), PARAM_COUNT, "{}: must store every parameter", label(p));
        for spec in PARAMS.iter() {
            assert!(p.params.contains_key(spec.key), "{}: missing '{}'", label(p), spec.key);
        }
        let w = p.wave.as_ref().unwrap_or_else(|| panic!("{}: must store its wave RAM", label(p)));
        assert_eq!(w.len(), wave::WAVE_LEN, "{}", label(p));
        let (state, _) = p.to_state();
        let any_on = Channel::ALL.iter().any(|c| state.values.bool(ParamId::channel(*c, ChannelField::On)));
        assert!(any_on, "{}: no channel enabled", label(p));
        assert!(state.values.0.iter().all(|v| v.is_finite()), "{}", label(p));
    }
}

#[test]
fn macros_are_complete_and_every_routing_moves_its_target() {
    let raw: serde_json::Value = serde_json::from_str(FACTORY_JSON).unwrap();
    let raw_presets = raw["presets"].as_array().unwrap();
    for (p, raw_p) in library().presets.iter().zip(raw_presets) {
        assert_eq!(raw_p["number"].as_u64(), Some(p.number as u64));
        let (state, _) = p.to_state();
        let stored = macro_values(&state.values);
        let raw_macros = raw_p["macros"].as_array().unwrap_or_else(|| panic!("{}: macros missing", label(p)));
        assert_eq!(raw_macros.len(), MACRO_COUNT, "{}: four macro lists", label(p));
        for (m, raw_slots) in raw_macros.iter().enumerate() {
            let routings: Vec<(ParamId, f32)> = state.macros.targets(m).collect();
            let raw_count = raw_slots.as_array().map_or(0, |s| s.len());
            // Nothing may be dropped while loading (unknown or non-modulatable target, duplicate,
            // depth below MIN_DEPTH, more than MACRO_SLOTS routings).
            assert_eq!(routings.len(), raw_count, "{}: macro {} lost routings while loading", label(p), m + 1);
            assert!(!routings.is_empty(), "{}: macro {} has no routing", label(p), m + 1);
            assert!(routings.len() <= MACRO_SLOTS, "{}", label(p));
            for (target, _) in &routings {
                assert!(target.spec().modulatable, "{}: {} is not modulatable", label(p), target.key());
                // Macro 0 % vs 100 % (the others at their stored positions) must move the target.
                let (mut lo, mut hi) = (stored, stored);
                lo[m] = 0.0;
                hi[m] = 1.0;
                let (mut v_lo, mut v_hi) = (ParamValues::defaults(), ParamValues::defaults());
                apply_macros(&state.values, lo, &state.macros, &mut v_lo);
                apply_macros(&state.values, hi, &state.macros, &mut v_hi);
                assert!(
                    (v_hi.get(*target) - v_lo.get(*target)).abs() > 1e-4,
                    "{}: macro {} -> {} does not move its target",
                    label(p),
                    m + 1,
                    target.key()
                );
            }
        }
        let mut sanitized = state.macros;
        sanitized.sanitize();
        assert_eq!(sanitized, state.macros, "{}", label(p));
    }
}

#[test]
fn hyrule_fanfare_is_the_init_state() {
    let lib = library();
    let p = lib.presets.iter().find(|p| p.number == INIT_NUMBER).expect("preset 014");
    assert_eq!(p.name, "Hyrule Fanfare");
    assert_eq!(p.category, Category::Lead);
    assert_eq!(p.icon, PresetIcon::Wav);
    assert!(p.params.is_empty(), "014 stores no parameters: it is the parameter defaults");
    assert!(p.wave.is_none(), "014 stores no wave: it is the default wave");
    assert_eq!(p.macros, MacroAssignments::factory_default());
    assert_eq!(p.description.ru, DESIGN_TWELVE[0].4);
    let (state, warnings) = p.to_state();
    assert!(warnings.is_empty());
    assert_eq!(state.values, ParamValues::defaults());
    assert_eq!(state.wave, wave::default_wave());
    assert_eq!(state.macros, MacroAssignments::factory_default());
    assert_eq!(state.values.chip(), ChipMode::Gb);
}

#[test]
fn design_presets_keep_their_identity() {
    let lib = library();
    for (name, category, chip, icon, ru) in DESIGN_TWELVE {
        let p = lib.presets.iter().find(|p| p.name == name).unwrap_or_else(|| panic!("design preset '{name}' missing"));
        assert_eq!(p.category, category, "{name}");
        assert_eq!(p.chip(), chip, "{name}");
        assert_eq!(p.icon, icon, "{name}");
        assert_eq!(p.description.ru, ru, "{name}: the design's description, verbatim");
        assert!(!p.description.en.is_empty(), "{name}: English translation");
    }
}

/// Six decimals without trailing zeros: the formatter of `pixl_params.listing_number`.
fn listing_number(x: f64) -> String {
    let s = format!("{x:.6}");
    let s = s.trim_end_matches('0').trim_end_matches('.');
    if s.is_empty() || s == "-0" {
        "0".to_string()
    } else {
        s.to_string()
    }
}

/// The listing `pixl_params.table_listing()` produces, built from the Rust definitions.
fn rust_listing() -> String {
    let mut lines = vec![
        "# The PIXL parameter table as mirrored by tools/presets/pixl_params.py.".to_string(),
        "# Written by tools/presets/generate.py; crates/pixl-core/tests/factory_library.rs".to_string(),
        "# rebuilds this listing from pixl_core::PARAMS and requires it to be identical.".to_string(),
    ];
    for spec in PARAMS.iter() {
        let (lo, hi) = spec.range();
        let (kind, skew) = match spec.kind {
            ParamKind::Float { skew, .. } => ("float", skew),
            ParamKind::Int { .. } => ("int", 1.0),
            ParamKind::Bool => ("bool", 1.0),
            ParamKind::Enum { .. } => ("enum", 1.0),
        };
        let mut fields = vec![
            "param".to_string(),
            spec.key.to_string(),
            spec.group.replace(' ', "_"),
            kind.to_string(),
            listing_number(lo as f64),
            listing_number(hi as f64),
            listing_number(skew as f64),
            listing_number(spec.default as f64),
            (if spec.modulatable { "mod" } else { "fixed" }).to_string(),
        ];
        if let ParamKind::Enum { variants } = spec.kind {
            fields.push(variants.join("|"));
        }
        lines.push(fields.join(" "));
    }
    lines.push(format!("macro_count {MACRO_COUNT}"));
    lines.push(format!("macro_slots {MACRO_SLOTS}"));
    lines.push(format!("min_depth {}", listing_number(MIN_DEPTH as f64)));
    lines.push(format!("macro_names {}", MACRO_NAMES.join(" ")));
    let defaults = MacroAssignments::factory_default();
    for m in 0..MACRO_COUNT {
        for (target, depth) in defaults.targets(m) {
            lines.push(format!("factory_default {m} {} {}", target.key(), listing_number(depth as f64)));
        }
    }
    lines.join("\n") + "\n"
}

#[test]
fn python_mirror_matches_the_parameter_table() {
    let rust = rust_listing();
    if rust != MIRROR_LISTING {
        let diff: Vec<String> = rust
            .lines()
            .zip(MIRROR_LISTING.lines())
            .filter(|(a, b)| a != b)
            .take(8)
            .map(|(a, b)| format!("  rust:   {a}\n  python: {b}"))
            .collect();
        panic!(
            "tools/presets/pixl_params.py no longer mirrors pixl-core ({} vs {} lines); update it and run \
             tools/presets/generate.py:\n{}",
            rust.lines().count(),
            MIRROR_LISTING.lines().count(),
            diff.join("\n")
        );
    }
}
